        detail: `<p style="text-align: center;"><span style="font-size: 18pt;"><strong>All About Bone and Joint Problems: Knee Pain - Osteoarthritis</strong></span></p>
<p style="text-align: center;">By Asst. Prof. Dr. Thaninnit Leerapun</p>
<strong>Knee pain, knee osteoarthritis.</strong> Symptoms include knee pain, knee swelling due to fluid buildup from inflammation, difficulty bearing weight when walking, bow-leggedness, and a grinding or cracking sound inside the joint during movement

<figure class="wp-block-image aligncenter"><img class="aligncenter wp-image-1105" src="https://doctorkeng.com/wordpress/wp-content/uploads/2020/04/20200410-taninnit-001.jpg" alt="" width="700" height="432" /></figure>
<br>
<strong><span style="font-size: 14pt;">Diagnosis</span></strong>
<br>
Diagnosis is made based on knee pain, knee swelling, and X-ray findings of joint space narrowing and osteophytes due to knee joint instability

<figure class="wp-block-image aligncenter"><img class="aligncenter wp-image-1106" src="https://doctorkeng.com/wordpress/wp-content/uploads/2020/04/20200410-taninnit-002.jpg" alt="" width="700" height="646" /></figure>
<br>
<span style="font-size: 14pt;"><strong>Treatment</strong></span>
<br>
involves taking anti-inflammatory and pain-reducing medication, along with applying cold compresses to the knee joint to reduce swelling and pain. We emphasize: use cold for the compress this could be ice wrapped in a cloth or a cold gel pack. If there's inflammation or fluid in the knee joint, the fluid can be drained to reduce inflammation, minimize damage to the joint surface, and alleviate pain.
<br>
<figure class="wp-block-image aligncenter"><img class="aligncenter wp-image-1107" src="https://doctorkeng.com/wordpress/wp-content/uploads/2020/04/20200410-taninnit-003.jpg" alt="" width="700" height="683" /></figure>
<br>
If the joint surface is severely damaged, leading to significant bow-leggedness and difficulty walking, the best treatment is total knee replacement surger
<br>
<figure class="wp-block-image aligncenter"><img class="aligncenter wp-image-1108" src="https://doctorkeng.com/wordpress/wp-content/uploads/2020/04/20200410-taninnit-004.jpg" alt="" width="700" height="816" /></figure>
<br>
<strong>Follow stories and various bone and joint issues on Blockdit at</strong> <a href="https://www.blockdit.com/doctorkeng" target="_blank" rel="noopener noreferrer">https://www.blockdit.com/doctorkeng</a>`,
